pub fn apply_inverse(inverse: &GltfMoveSkinInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveSkinInverseOperation::Insert { position, .. } if *position > after.document.skins.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/skins", "position must be within the collection")), GltfMoveSkinInverseOperation::Delete { index, .. } if *index >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "index must address an item")), GltfMoveSkinInverseOperation::Move { index, position } if *index >= after.document.skins.len() || *position >= after.document.skins.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/skins", "indices must address items")), GltfMoveSkinInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.skins.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.skins.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/skins", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveSkinInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Skins, &Change::Insert(*position))?; next.document.skins.insert(*position, item.clone());  }, GltfMoveSkinInverseOperation::Delete { index, .. } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, None, None)?;  }, GltfMoveSkinInverseOperation::Move { index, position } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, Some(*position), None)?;  }, GltfMoveSkinInverseOperation::Reorder { order } => { skins_op(&mut next, GltfTopLevelFamily::Skins, order[0], None, Some(order))?;  } } Ok(next) }
